use std::fmt;

use serde::Serialize;

/// The error codes of the protocol; no other code is ever sent.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum ErrorCode {
    InvalidRequest,
    MissingParameter,
    InvalidParameterValue,
    QueueNameInvalid,
    QueueAlreadyExists,
    QueueDoesNotExist,
    ReceiptHandleInvalid,
    ReceiptHandleExpired,
    UnsupportedOperation,
    LimitExceeded,
}

/// A failed command: the code is the contract, the message is for humans.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Error {
    pub code: ErrorCode,
    pub message: String,
}

impl Error {
    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }

    pub fn invalid_parameter(name: &str) -> Self {
        Self::new(
            ErrorCode::InvalidParameterValue,
            format!("parameter {name} has the wrong type or a value that is not allowed"),
        )
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:?}: {}", self.code, self.message)
    }
}

impl std::error::Error for Error {}

//! Numeric building blocks: range-checked integers, the virtual clock and id counters.

use serde::Serialize;

/// An integer known to lie in `MIN..=MAX`; the only ways to build one check the range.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
pub struct Bounded<const MIN: u32, const MAX: u32>(u32);

impl<const MIN: u32, const MAX: u32> Bounded<MIN, MAX> {
    /// A compile-time checked constant, for defaults taken from the specification.
    pub const fn literal<const V: u32>() -> Self {
        const { assert!(MIN <= V && V <= MAX) };
        Self(V)
    }

    pub fn get(self) -> u32 {
        self.0
    }
}

impl<const MIN: u32, const MAX: u32> TryFrom<i64> for Bounded<MIN, MAX> {
    type Error = OutOfRange;

    fn try_from(value: i64) -> Result<Self, OutOfRange> {
        u32::try_from(value)
            .ok()
            .filter(|v| (MIN..=MAX).contains(v))
            .map(Self)
            .ok_or(OutOfRange)
    }
}

/// The value is outside the range of the target type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OutOfRange;

pub type VisibilityTimeout = Bounded<0, 43_200>;
pub type DelaySeconds = Bounded<0, 900>;
pub type RetentionSeconds = Bounded<60, 1_209_600>;
pub type MaxReceiveCount = Bounded<1, 1000>;
pub type MaxMessages = Bounded<1, 10>;
pub type TickSeconds = Bounded<0, 1_209_600>;

/// A value of the virtual clock, in seconds since it started.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
pub struct Timestamp(u64);

impl Timestamp {
    pub const START: Self = Self(0);

    /// Saturates: behavior past 4000000000 is unspecified, but must not wrap.
    pub fn plus(self, seconds: u32) -> Self {
        Self(self.0.saturating_add(u64::from(seconds)))
    }
}

/// Hands out 1, 2, 3, ... and remembers how many it issued.
#[derive(Debug, Default)]
pub struct Counter {
    issued: u64,
}

impl Counter {
    pub fn next(&mut self) -> u64 {
        self.issued += 1;
        self.issued
    }

    pub fn issued(&self) -> u64 {
        self.issued
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    type Small = Bounded<2, 5>;

    #[test]
    fn bounded_accepts_exactly_its_inclusive_range() {
        let cases = [
            (1, None),
            (2, Some(2)),
            (5, Some(5)),
            (6, None),
            (-1, None),
            (i64::MAX, None),
        ];
        for (input, expected) in cases {
            let actual = Small::try_from(input).ok().map(Small::get);
            assert_eq!(actual, expected, "input {input}");
        }
    }

    #[test]
    fn timestamp_plus_saturates() {
        let near_end = Timestamp(u64::MAX - 1);
        assert_eq!(near_end.plus(10), Timestamp(u64::MAX));
    }

    #[test]
    fn counter_starts_at_one() {
        let mut counter = Counter::default();
        assert_eq!((counter.next(), counter.next()), (1, 2));
        assert_eq!(counter.issued(), 2);
    }
}

//! Strings with a validity rule. Each type can only be built through `parse`.

use std::borrow::Borrow;

use serde::Serialize;

const FIFO_SUFFIX: &str = ".fifo";

fn is_token_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-'
}

fn is_token(text: &str, max_len: usize) -> bool {
    (1..=max_len).contains(&text.len()) && text.bytes().all(is_token_byte)
}

/// A queue name that follows the naming rules. Ordering is by byte value.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
pub struct QueueName(String);

impl QueueName {
    pub fn parse(text: &str) -> Option<Self> {
        let valid = match text.strip_suffix(FIFO_SUFFIX) {
            Some(stem) => is_token(stem, 75),
            None => is_token(text, 80),
        };
        valid.then(|| Self(text.to_owned()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }

    /// Whether the name carries the suffix reserved for FIFO queues.
    pub fn has_fifo_suffix(&self) -> bool {
        self.0.ends_with(FIFO_SUFFIX)
    }
}

// Lets maps keyed by `QueueName` be searched with any `&str`; the derived
// `Ord` and `Hash` of the wrapper agree with those of `str`.
impl Borrow<str> for QueueName {
    fn borrow(&self) -> &str {
        &self.0
    }
}

/// A message body of 1 to 1024 bytes.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Body(String);

impl Body {
    pub fn parse(text: &str) -> Option<Self> {
        (1..=1024).contains(&text.len()).then(|| Self(text.to_owned()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// The group of a message in a FIFO queue.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize)]
pub struct GroupId(String);

impl GroupId {
    pub fn parse(text: &str) -> Option<Self> {
        is_token(text, 128).then(|| Self(text.to_owned()))
    }
}

/// A caller-chosen deduplication id of a FIFO send.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeduplicationId(String);

impl DeduplicationId {
    pub fn parse(text: &str) -> Option<Self> {
        is_token(text, 128).then(|| Self(text.to_owned()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// The key under which a queue remembers a send for deduplication. A body used
/// as an id and a `DeduplicationId` share one namespace, so this has no
/// validity rule.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct DedupKey(String);

impl DedupKey {
    pub fn new(text: &str) -> Self {
        Self(text.to_owned())
    }
}

// Same contract as for `QueueName`: lookups by `&str` need no allocation.
impl Borrow<str> for DedupKey {
    fn borrow(&self) -> &str {
        &self.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn queue_name_syntax() {
        let long_plain = "a".repeat(80);
        let long_fifo = format!("{}.fifo", "a".repeat(75));
        let too_long_plain = "a".repeat(81);
        let too_long_fifo = format!("{}.fifo", "a".repeat(76));
        let cases = [
            ("jobs", true),
            ("A_z-9", true),
            ("jobs.fifo", true),
            (long_plain.as_str(), true),
            (long_fifo.as_str(), true),
            ("", false),
            (".fifo", false),
            ("a.fifo.fifo", false),
            ("a.b", false),
            ("jobs fifo", false),
            ("caf\u{e9}", false),
            (too_long_plain.as_str(), false),
            (too_long_fifo.as_str(), false),
        ];
        for (name, valid) in cases {
            assert_eq!(QueueName::parse(name).is_some(), valid, "name {name:?}");
        }
    }

    #[test]
    fn queue_names_sort_by_byte_value() {
        let mut names: Vec<QueueName> = ["a", "_", "Z", "9", "a.fifo", "a-"]
            .into_iter()
            .map(|n| QueueName::parse(n).expect("valid name"))
            .collect();
        names.sort();
        let sorted: Vec<&str> = names.iter().map(QueueName::as_str).collect();
        assert_eq!(sorted, ["9", "Z", "_", "a", "a-", "a.fifo"]);
    }

    #[test]
    fn body_length_is_counted_in_bytes() {
        let two_byte_chars = "\u{e9}".repeat(512);
        let one_too_many = format!("{two_byte_chars}x");
        assert!(Body::parse(&two_byte_chars).is_some());
        assert!(Body::parse(&one_too_many).is_none());
        assert!(Body::parse("").is_none());
    }

    #[test]
    fn group_ids_follow_the_token_rule() {
        let cases = [("g-1_", true), ("", false), ("a b", false), (&"x".repeat(129), false)];
        for (text, valid) in cases {
            assert_eq!(GroupId::parse(text).is_some(), valid, "id {text:?}");
        }
    }
}

//! Identifiers issued by the process.

use std::fmt;

use serde::{Serialize, Serializer};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MessageId(u64);

impl MessageId {
    pub fn new(number: u64) -> Self {
        Self(number)
    }
}

impl fmt::Display for MessageId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "m-{}", self.0)
    }
}

impl Serialize for MessageId {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.collect_str(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ReceiptHandle(u64);

impl ReceiptHandle {
    pub fn new(number: u64) -> Self {
        Self(number)
    }

    /// Recognizes exactly the strings `Display` can produce for a number up to
    /// `issued`: no sign, no leading zero, no surrounding characters.
    pub fn parse(text: &str, issued: u64) -> Option<Self> {
        let digits = text.strip_prefix("r-")?;
        if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        let number: u64 = digits.parse().ok()?;
        (number <= issued).then_some(Self(number))
    }
}

impl fmt::Display for ReceiptHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "r-{}", self.0)
    }
}

impl Serialize for ReceiptHandle {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.collect_str(self)
    }
}

/// Position of a message among those added to one FIFO queue.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct SequenceNumber(u64);

impl SequenceNumber {
    pub fn new(number: u64) -> Self {
        Self(number)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn receipt_handles_parse_only_canonical_issued_numbers() {
        let cases = [
            ("r-1", Some(1)),
            ("r-12", Some(12)),
            ("r-13", None),
            ("r-0", None),
            ("r-01", None),
            ("r-+1", None),
            ("R-1", None),
            ("r-1 ", None),
            ("r-", None),
            ("1", None),
            ("r-99999999999999999999999", None),
        ];
        for (text, expected) in cases {
            let actual = ReceiptHandle::parse(text, 12);
            assert_eq!(actual, expected.map(ReceiptHandle::new), "handle {text:?}");
        }
    }

    #[test]
    fn ids_render_with_their_prefix() {
        assert_eq!(MessageId::new(7).to_string(), "m-7");
        assert_eq!(ReceiptHandle::new(3).to_string(), "r-3");
    }
}

